/** Dil başına tek URL: TR /slug, diğerleri /<dil>/slug. */
export const kargoUrl = (l: KLang) => (l === 'tr' ? `/${KARGO.tr.slug}` : `/${l}/${KARGO[l].slug}`);
export const parseKargoSlug = (l: KLang, slug: string) => KARGO[l].slug === slug;
/** 10 dil + x-default (EN). */
export const kargoLanguages = (): Record<string, string> => ({
  ...Object.fromEntries(KLANGS.map((l) => [l, `${KARGO_SITE}${kargoUrl(l)}`])),
  'x-default': `${KARGO_SITE}${kargoUrl('en')}`,
});
